# install-agency.ps1
# Self-contained Agency installer.
# Run this on any fresh Windows 11 PC to set up the full agency stack.
# Usage:
#   First time:  .\install-agency.ps1
#   With project path: .\install-agency.ps1 -ProjectPath "F:\my-project"
#   Silent re-run:     .\install-agency.ps1 -ProjectPath "F:\my-project" -Silent
#
# What it does:
#   1. Extracts all agency scripts to %USERPROFILE%\.agency\
#   2. Runs global install (prereqs, repos, openviking, agent roles, config)
#   3. Sets up the project at the given path (or prompts for one)
#   4. On re-run: skips completed steps, updates scripts, resumes where needed

param(
    [string]$ProjectPath = "",
    [switch]$Silent
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$GLOBAL = Join-Path $env:USERPROFILE ".agency"
$SCRIPTS_DIR = Join-Path $GLOBAL "scripts"
$STAMP = Join-Path $GLOBAL ".install-version"
$VERSION = "1.0.0"

function Write-Step { param($msg) Write-Host "" ; Write-Host "=== $msg ===" -ForegroundColor Cyan }
function Write-OK   { param($msg) Write-Host "  [OK] $msg" -ForegroundColor Green }
function Write-Skip { param($msg) Write-Host "  [--] $msg (skipped)" -ForegroundColor Gray }
function Write-Warn { param($msg) Write-Host "  [!!] $msg" -ForegroundColor Yellow }

Write-Host ""
Write-Host "Agency Installer v$VERSION" -ForegroundColor Magenta
Write-Host "==============================" -ForegroundColor Magenta

# -----------------------------------------------------------------------
# STEP 1: Extract all embedded scripts
# Scripts are base64-encoded to avoid all heredoc/escaping issues.
# Always re-extracted so updates to the installer update the scripts.
# -----------------------------------------------------------------------
Write-Step "Extracting agency scripts"

$scriptMap = @{
    "global\install-global.ps1" = ""
    "global\scripts\g01-prereqs.ps1" = ""
    "global\scripts\g02-repos.ps1" = ""
    "global\scripts\g03-openviking.ps1" = ""
    "global\scripts\g04-agent-roles.ps1" = ""
    "global\scripts\g05-global-config.ps1" = ""
    "global\scripts\g06-verify.ps1" = ""
    "project\setup-project.ps1" = ""
    "project\launch.ps1" = ""
    "project\watcher.ps1" = ""
    "project\worker-loop.ps1" = ""
    "project\regenerate-claude-md.ps1" = ""
    "project\scripts\p01-prompt.ps1" = ""
    "project\scripts\p02-folders.ps1" = ""
    "project\scripts\p03-env.ps1" = ""
    "project\scripts\p04-claude-md.ps1" = ""
    "project\scripts\p05-verify.ps1" = ""
}

foreach ($entry in $scriptMap.GetEnumerator()) {
    $dest = Join-Path $GLOBAL $entry.Key
    $dir  = Split-Path $dest -Parent
    New-Item -ItemType Directory -Force -Path $dir | Out-Null
    $bytes = [System.Convert]::FromBase64String($entry.Value)
    [System.IO.File]::WriteAllBytes($dest, $bytes)
}
Write-OK "All scripts extracted to $GLOBAL"

# -----------------------------------------------------------------------
# STEP 2: Run global install
# Idempotent - skips completed steps automatically
# -----------------------------------------------------------------------
Write-Step "Running global install"

$env:AGENCY_GLOBAL = $GLOBAL
$globalInstall = Join-Path $GLOBAL "global\install-global.ps1"

# Run each global sub-script directly so we get proper error reporting
$globalScripts = @(
    "global\scripts\g01-prereqs.ps1",
    "global\scripts\g02-repos.ps1",
    "global\scripts\g03-openviking.ps1",
    "global\scripts\g04-agent-roles.ps1",
    "global\scripts\g05-global-config.ps1",
    "global\scripts\g06-verify.ps1"
)

foreach ($script in $globalScripts) {
    $path = Join-Path $GLOBAL $script
    Write-Host "  Running $([System.IO.Path]::GetFileName($path))..." -ForegroundColor Gray
    & $path
    if ($LASTEXITCODE -and $LASTEXITCODE -ne 0) {
        Write-Host "FAILED at $script" -ForegroundColor Red
        exit 1
    }
}

# -----------------------------------------------------------------------
# STEP 3: Determine project path
# -----------------------------------------------------------------------
Write-Step "Project setup"

if (-not $ProjectPath) {
    if ($Silent) {
        Write-Host "ERROR: -ProjectPath required in silent mode" -ForegroundColor Red
        exit 1
    }
    Write-Host ""
    Write-Host "  Where should the project be created?" -ForegroundColor White
    Write-Host "  Enter full path (e.g. F:\my-project): " -ForegroundColor White -NoNewline
    $ProjectPath = Read-Host
}

$ProjectPath = $ProjectPath.Trim().TrimEnd("\")

# Check if already set up
$metaFile = Join-Path $ProjectPath ".agency-project.json"
if (Test-Path $metaFile) {
    Write-Warn "Project already set up at $ProjectPath"
    Write-Host "  Re-running will regenerate CLAUDE.md files and update scripts." -ForegroundColor Gray
    if (-not $Silent) {
        Write-Host "  Continue? (Y/n): " -ForegroundColor White -NoNewline
        $confirm = Read-Host
        if ($confirm -eq "n" -or $confirm -eq "N") { exit 0 }
    }
}

New-Item -ItemType Directory -Force -Path $ProjectPath | Out-Null

# -----------------------------------------------------------------------
# STEP 4: Copy project scripts into project root
# -----------------------------------------------------------------------
Write-Step "Installing project scripts"

$projectScripts = @(
    "project\launch.ps1",
    "project\watcher.ps1",
    "project\worker-loop.ps1",
    "project\regenerate-claude-md.ps1",
    "project\setup-project.ps1"
)

foreach ($script in $projectScripts) {
    $src  = Join-Path $GLOBAL $script
    $dest = Join-Path $ProjectPath ([System.IO.Path]::GetFileName($script))
    Copy-Item $src $dest -Force
    Write-OK ([System.IO.Path]::GetFileName($script))
}

# Also copy setup sub-scripts
$setupScriptsDir = Join-Path $ProjectPath "scripts"
New-Item -ItemType Directory -Force -Path $setupScriptsDir | Out-Null
$pScripts = @("p01-prompt.ps1","p02-folders.ps1","p03-env.ps1","p04-claude-md.ps1","p05-verify.ps1")
foreach ($s in $pScripts) {
    $src  = Join-Path $GLOBAL "project\scripts\$s"
    $dest = Join-Path $setupScriptsDir $s
    Copy-Item $src $dest -Force
}
Write-OK "setup sub-scripts"

# -----------------------------------------------------------------------
# STEP 5: Run project setup
# -----------------------------------------------------------------------
Write-Step "Setting up project"

$env:AGENCY_GLOBAL  = $GLOBAL
$env:AGENCY_PROJECT = $ProjectPath

$pScriptPaths = @(
    (Join-Path $setupScriptsDir "p01-prompt.ps1"),
    (Join-Path $setupScriptsDir "p02-folders.ps1"),
    (Join-Path $setupScriptsDir "p03-env.ps1"),
    (Join-Path $setupScriptsDir "p04-claude-md.ps1"),
    (Join-Path $setupScriptsDir "p05-verify.ps1")
)

foreach ($script in $pScriptPaths) {
    Write-Host "  Running $([System.IO.Path]::GetFileName($script))..." -ForegroundColor Gray
    & $script
    if ($LASTEXITCODE -and $LASTEXITCODE -ne 0) {
        Write-Host "FAILED at $script" -ForegroundColor Red
        exit 1
    }
}

# -----------------------------------------------------------------------
# STEP 6: Update .gitignore
# -----------------------------------------------------------------------
$gitignore = Join-Path $ProjectPath ".gitignore"
$agencyIgnore = @"

# Agency runtime files
.env
.agency-project.json
.agency-launch/
context/tasks/
context/handoffs/
logs/
"@

if (Test-Path $gitignore) {
    $existing = Get-Content $gitignore -Raw
    if ($existing -notmatch "Agency runtime") {
        Add-Content $gitignore $agencyIgnore
        Write-OK ".gitignore updated"
    } else {
        Write-Skip ".gitignore already has agency entries"
    }
} else {
    $agencyIgnore | Set-Content $gitignore -Encoding UTF8
    Write-OK ".gitignore created"
}

# -----------------------------------------------------------------------
# STEP 7: Stamp install version
# -----------------------------------------------------------------------
$VERSION | Set-Content $STAMP -Encoding UTF8

# -----------------------------------------------------------------------
# Done
# -----------------------------------------------------------------------
Write-Host ""
Write-Host "==============================" -ForegroundColor Magenta
Write-Host "  Agency installed!" -ForegroundColor Magenta
Write-Host "==============================" -ForegroundColor Magenta
Write-Host ""
Write-Host "  Project : $ProjectPath" -ForegroundColor White
Write-Host "  Global  : $GLOBAL" -ForegroundColor White
Write-Host ""
Write-Host "  Next steps:" -ForegroundColor Cyan
Write-Host "    1. Fill in API key:" -ForegroundColor White
Write-Host "       notepad \"$ProjectPath\.env\"" -ForegroundColor Gray
Write-Host "    2. Fill in your developer profile (once):" -ForegroundColor White
Write-Host "       notepad \"$GLOBAL\config\user-context.md\"" -ForegroundColor Gray
Write-Host "    3. Add Anthropic key to OpenViking config:" -ForegroundColor White
Write-Host "       notepad \"$env:USERPROFILE\.openviking\ov.conf\"" -ForegroundColor Gray
Write-Host "    4. Launch:" -ForegroundColor White
Write-Host "       cd \"$ProjectPath\" ; .\launch.ps1" -ForegroundColor Gray
Write-Host ""